package com.flippingfriend.companion;
import com.flippingfriend.model.ItemFeatures; import org.junit.Test; import static org.junit.Assert.*;
public class BuyReplacementUnwindLossInputContextComposerTest {
 @Test public void exactInputsComposeAndPreserveOrderedEvidence(){BuyReplacementExpectedSlotOccupancyEvaluationSet s=source();ItemFeatures f=ItemFeatures.unknown(s.getItemId());BuyReplacementUnwindLossInputContext r=new BuyReplacementUnwindLossInputContextComposer().compose(s,990,f,300,1100,1100);assertNotNull(r);assertEquals(990,r.getCurrentLowPrice());assertEquals(0.0,r.getVolatility(),0.0);assertEquals(300,r.getBucketSeconds());assertSame(s.getEvaluations(),r.getEvaluations());}
 @Test public void unavailableMismatchedStaleAndMalformedInputsFailClosed(){BuyReplacementExpectedSlotOccupancyEvaluationSet s=source();BuyReplacementUnwindLossInputContextComposer c=new BuyReplacementUnwindLossInputContextComposer();assertNull(c.compose(null,990,ItemFeatures.unknown(s.getItemId()),300,1100,1100));assertNull(c.compose(s,990,ItemFeatures.unknown(s.getItemId()+1),300,1100,1100));assertNull(c.compose(s,990,ItemFeatures.unknown(s.getItemId()),300,979,1100));assertNull(c.compose(s,0,ItemFeatures.unknown(s.getItemId()),300,1100,1100));}
 @Test public void contractsCarryNoUnwindProfitRiskRankingSelectionOrAuthorization()throws Exception{for(String f:new String[]{"BuyReplacementUnwindLossInputContext.java","BuyReplacementUnwindLossInputContextComposer.java"}){String x=java.nio.file.Files.readString(java.nio.file.Path.of("src/main/java/com/flippingfriend/companion/"+f));for(String forbidden:new String[]{"unwindCost(","getUnwindLoss","expectedProfit","worstLoss","kelly","expectedGpPerSlotHour","selected","score","rank","PortfolioCandidate","PolicyDecision","OfferLifecycleAction","REPLACEMENT_AUTHORIZED"})assertFalse(x.contains(forbidden));}}
 static BuyReplacementUnwindLossInputContext contextForCompanionTests(){BuyReplacementExpectedSlotOccupancyEvaluationSet s=source();return new BuyReplacementUnwindLossInputContextComposer().compose(s,990,ItemFeatures.unknown(s.getItemId()),300,1100,1100);} private static BuyReplacementExpectedSlotOccupancyEvaluationSet source(){return BuyReplacementExpectedSlotOccupancyEvaluatorTest.evaluationSetForCompanionTests();}
}
